package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl = template.Must(template.New("search").Parse(`
<html><body>
<h1>Employee Directory</h1>
<form method="GET" action="/search">
  <input name="q" value="{{.Query}}" placeholder="Search by name or department">
  <input name="field" value="{{.Field}}" type="hidden">
  <button>Search</button>
</form>
<table>{{range .Results}}<tr><td>{{.Name}}</td><td>{{.Dept}}</td><td>{{.Email}}</td></tr>{{end}}</table>
</body></html>`))

type Employee struct {
	Name string
	Dept string
	Email string
}

type PageData struct {
	Query   string
	Field   string
	Results []Employee
}

func generateCSRFToken() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	field := r.URL.Query().Get("field")

	// Validate field parameter against allowlist
	allowedFields := map[string]bool{"name": true, "department": true, "email": true}
	if field == "" {
		field = "name"
	}
	if !allowedFields[field] {
		http.Error(w, "Invalid field", 400)
		return
	}

	// Sanitize query - remove obvious SQL keywords
	query = strings.ReplaceAll(query, ";", "")
	query = strings.ReplaceAll(query, "--", "")

	// Build query with parameterized field (validated above) but inline query value
	// for LIKE pattern matching with wildcards
	sqlQuery := fmt.Sprintf(
		"SELECT name, department, email FROM employees WHERE %s ILIKE '%%%s%%' LIMIT 50",
		field, query,
	)

	rows, err := db.Query(sqlQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search error", 500)
		return
	}
	defer rows.Close()

	var results []Employee
	for rows.Next() {
		var e Employee
		if err := rows.Scan(&e.Name, &e.Dept, &e.Email); err != nil {
			continue
		}
		results = append(results, e)
	}

	w.Header().Set("X-Request-ID", generateCSRFToken())
	tmpl.Execute(w, PageData{Query: query, Field: field, Results: results})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(10)

	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
